  "enrollment": 12,
  "interventions": [
    {
      "description": "The unique style of Art Meditation where mindfulness (heightened awareness) is achieved by combination of movement and focus on Chinese Tao Calligraphy while chanting a mantra. The practitioners repeatedly trace the lines of Tao calligraphy with fingers and chant the mantra. This enables them to achieve deep concentration, while maintaining fully alert state. The practice can be done in sitting or standing, depending on the health status and age.",
      "id": 1,
      "name": "Mindfulness practice with Calligraphy",
